export function teamLogoFor(series,category,row){
 if(!['f1','wec','imsa','formula-e'].includes(series))return null;
 // Driver identity is never used to guess a team; only upstream team/manufacturer fields.
 const isDriver=/driver/i.test(category);
 const value=[row.manufacturer,row.team,isDriver?'':row.name].filter(v=>typeof v==='string').join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const names=[['mercedes',/mercedes/],['bmw',/\bbmw\b/],['ferrari',/ferrari/],['porsche',/porsche/],['toyota',/toyota/],['alpine',/alpine/],['astonmartin',/aston\s*martin/],['cadillac',/cadillac/],['acura',/acura/],['genesis',/genesis/],['peugeot',/peugeot/],['mclaren',/mclaren/],['audi',/\baudi\b/],['racingbulls',/racing\s*bulls|\brb\s*f1/],['redbull',/red\s*bull/],['haas',/\bhaas\b/],['williams',/williams/],['lexus',/lexus/],['jaguar',/jaguar/],['nissan',/nissan/],['mahindra',/mahindra/],['dsautomobiles',/ds\s+(?:automobiles|penske|performance)/],['maserati',/maserati/],['citroen',/citroen/],['cupra',/cupra/],['lamborghini',/lamborghini/],['ford',/\bford\b/],['chevrolet',/chevrolet|corvette/],['honda',/\bhonda\b/]];
 return names.find(([,pattern])=>pattern.test(value))?.[0]??null;
}
